SELECT COUNT(DISTINCT ur.user_id)
FROM sys_user_role ur
         JOIN sys_role r ON r.id = ur.role_id
WHERE r.code = #{roleCode}
  AND ur.user_id IN

    #{userId}

SELECT DISTINCT u.id FROM sys_user_role ur JOIN sys_role r ON r.id = ur.role_id JOIN sys_user u ON u.id = ur.user_id WHERE r.status = 1 AND u.status = 1 AND ur.role_id IN
#{roleId}
ORDER BY u.id
